public int maxPoints(int[][] points) {
    int n = points.length;
    if (n <= 2) return n;
    int best = 2;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int count = 2;
            for (int k = j + 1; k < n; k++) {
                if (collinear(points[i], points[j], points[k])) {
                    count++;
                }
            }
            best = Math.max(best, count);
        }
    }
    return best;
}

private boolean collinear(int[] a, int[] b, int[] c) {
    long cross = (long) (b[0] - a[0]) * (c[1] - a[1])
               - (long) (b[1] - a[1]) * (c[0] - a[0]);
    return cross == 0;
}

